    "Selvä!": "Forstået!",
    "Kerää mahdollisimman paljon pisteitä ja läpäise tasot yhdistämällä kaksi suurinta palloa. Peli päättyy, jos pallot painavat molempia nappeja yhtä aikaa.": "Saml så mange point som muligt, og klar banerne ved at sætte de to største bolde sammen. Spillet slutter, hvis boldene trykker på begge knapper på én gang.",
    "Kerää kahdessa minuutissa niin paljon pisteitä kuin ehdit. Nappeihin ei voi hävitä.": "Saml så mange point, du kan nå på to minutter. Du kan ikke tabe på knapperne.",
    "Tavoite vaihtuu joka päivä klo 15. Kaikilla on sama pallojärjestys ja sama tavoite.": "Målet skifter hver dag kl. 15 (finsk tid). Alle får samme kuglerækkefølge og samme mål.",
    "Ei mitään, vain rentoutumista. Pisteitä ei lasketa, eikä peliä voi hävitä.": "Ingenting, bare slap af. Der tælles ingen point, og du kan ikke tabe.",
    "Kerää mahdollisimman paljon pisteitä, kun painovoiman suunta vaihtuu muutaman sekunnin välein. Peli päättyy, jos pallot painavat molempia nappeja.": "Saml så mange point som muligt, mens tyngdekraftens retning skifter med få sekunders mellemrum. Spillet slutter, hvis boldene trykker på begge knapper.",
    "Suorita {1} tehtävää järjestyksessä. Jokaisella tehtävällä on oma tavoitteensa, esimerkiksi tietty pallo rajatuilla laukauksilla tai pisteitä aikarajassa.": "Gennemfør {1} missioner i rækkefølge. Hver mission har sit eget mål, fx en bestemt bold med et begrænset antal skud eller point inden for en tidsgrænse.",
