    "Ammu lippupalloja junavaunuun. Kaksi samaa maata yhdistyy isommaksi maaksi. Mikä mahtaa olla suurin?": "Skyd flagbolde ind i togvognen. To ens lande smelter sammen til et større land. Hvad mon det største er?",
    "Ammu jumalapalloja vaunuun. Kaksi samaa jumalaa yhdistyy mahtavammaksi. Kuka on mahtavin kaikista?": "Skyd gudebolde ind i vognen. To ens guder smelter sammen til en mægtigere. Hvem er den mægtigste af alle?",
    "Ammu sydänpalloja vaunuun. Kaksi samaa sydäntä yhdistyy isommaksi. Millainen on suurin sydän?": "Skyd hjertebolde ind i vognen. To ens hjerter smelter sammen til et større. Hvordan ser det største hjerte ud?",
    "Ammu laskupalloja vaunuun. Kaksi samaa laskua yhdistyy vaikeammaksi. Mikä on vaikein lasku?": "Skyd regnestykkebolde ind i vognen. To ens regnestykker smelter sammen til et sværere. Hvad er det sværeste regnestykke?",
