    "Joka {0}. laukauksella vaunuun putoaa kivi, joka ei yhdisty. Se hajoaa, kun sen vieressä yhdistetään palloja kaksi kertaa.": "Hvert {0}. skud falder en sten ned i vognen. Den smelter ikke sammen og går i stykker, når bolde sættes sammen ved siden af den to gange.",
