    "Selvä!": "Alles klar!",
    "Kerää mahdollisimman paljon pisteitä ja läpäise tasot yhdistämällä kaksi suurinta palloa. Peli päättyy, jos pallot painavat molempia nappeja yhtä aikaa.": "Sammle möglichst viele Punkte und schaffe die Level, indem du die zwei größten Kugeln verschmilzt. Das Spiel endet, wenn die Kugeln beide Knöpfe gleichzeitig drücken.",
    "Kerää kahdessa minuutissa niin paljon pisteitä kuin ehdit. Nappeihin ei voi hävitä.": "Sammle in zwei Minuten so viele Punkte wie möglich. An den Knöpfen kannst du nicht verlieren.",
    "Tavoite vaihtuu joka päivä klo 15. Kaikilla on sama pallojärjestys ja sama tavoite.": "Das Ziel wechselt jeden Tag um 15 Uhr (finnische Zeit). Alle bekommen dieselbe Ballreihenfolge und dasselbe Ziel.",
    "Ei mitään, vain rentoutumista. Pisteitä ei lasketa, eikä peliä voi hävitä.": "Nichts, einfach entspannen. Es werden keine Punkte gezählt und du kannst nicht verlieren.",
    "Kerää mahdollisimman paljon pisteitä, kun painovoiman suunta vaihtuu muutaman sekunnin välein. Peli päättyy, jos pallot painavat molempia nappeja.": "Sammle möglichst viele Punkte, während die Schwerkraft alle paar Sekunden die Richtung wechselt. Das Spiel endet, wenn die Kugeln beide Knöpfe drücken.",
    "Suorita {1} tehtävää järjestyksessä. Jokaisella tehtävällä on oma tavoitteensa, esimerkiksi tietty pallo rajatuilla laukauksilla tai pisteitä aikarajassa.": "Erledige {1} Missionen der Reihe nach. Jede Mission hat ihr eigenes Ziel, etwa eine bestimmte Kugel mit begrenzten Schüssen oder Punkte im Zeitlimit.",
