    "Erikoisasu pukee koko hahmon kerralla. Valitse Ei erikoisasua, niin omat valintasi palaavat.": "Ein Spezialkostüm kleidet die ganze Figur auf einmal. Wähle Kein Kostüm, um deine eigene Auswahl zurückzubekommen.",
