    "Ammu lippupalloja junavaunuun. Kaksi samaa maata yhdistyy isommaksi maaksi. Mikä mahtaa olla suurin?": "Schieß Flaggenkugeln in den Zugwaggon. Zwei gleiche Länder verschmelzen zu einem größeren. Welches ist wohl das größte?",
    "Ammu jumalapalloja vaunuun. Kaksi samaa jumalaa yhdistyy mahtavammaksi. Kuka on mahtavin kaikista?": "Schieß Götterkugeln in den Waggon. Zwei gleiche Götter verschmelzen zu einem mächtigeren. Wer ist der Mächtigste von allen?",
    "Ammu sydänpalloja vaunuun. Kaksi samaa sydäntä yhdistyy isommaksi. Millainen on suurin sydän?": "Schieß Herzkugeln in den Waggon. Zwei gleiche Herzen verschmelzen zu einem größeren. Wie sieht das größte Herz aus?",
    "Ammu laskupalloja vaunuun. Kaksi samaa laskua yhdistyy vaikeammaksi. Mikä on vaikein lasku?": "Schieß Aufgabenkugeln in den Waggon. Zwei gleiche Aufgaben verschmelzen zu einer schwierigeren. Was ist die schwierigste Aufgabe?",
