    "Joka {0}. laukauksella vaunuun putoaa kivi, joka ei yhdisty. Se hajoaa, kun sen vieressä yhdistetään palloja kaksi kertaa.": "Bei jedem {0}. Schuss fällt ein Stein in den Waggon. Er verschmilzt nicht und zerbricht, wenn neben ihm zweimal Kugeln verschmelzen.",
