    "Välillä juna kaartaa: varoituksen jälkeen vaunu kallistuu ja pallot valuvat sivulle.": "Ab und zu fährt der Zug eine Kurve: nach einer Warnung neigt sich der Waggon und die Kugeln rutschen zur Seite.",
