    "Kun saat {0}, vaunuun saapuu pomo. Voita se yhdistämällä palloja sen vieressä.": "Wenn du {0} bekommst, kommt ein Boss in den Waggon. Besiege ihn, indem du neben ihm Kugeln verschmilzt.",
