    "Pelialue: vaunu täynnä lippupalloja": "Play area: a wagon full of flag balls",
    "<b>Tähtää</b> hiirellä tai sormella. Mitä kauemmas osoitat, sitä kovempaa pallo lentää.": "<b>Aim</b> with the mouse or your finger. The further you point, the harder the ball flies.",
    "<b>Ammu</b> klikkaamalla tai nostamalla sormen ruudulta.": "<b>Shoot</b> by clicking or lifting your finger off the screen.",
    "Kevyt laukaus laskee pallon varovasti, kova laukaus <b>tönii ja litistää</b> muita.": "A soft shot lowers the ball gently, a hard shot <b>pushes and squashes</b> the others.",
    "Vaunun seinissä on kaksi nappia. Jos pallot koskettavat <b>molempia nappeja</b> yhtä aikaa, peli päättyy.": "There are two buttons on the wagon walls. If balls touch <b>both buttons</b> at the same time, the game ends.",
    "Joka <b>40 000 pisteellä</b> saat <b>ruletin</b>. Se arpoo heilautuksen, mustan aukon, magneetin, ei mitään tai harvoin <b>jokeripallon</b>, joka yhdistyy minkä tahansa pallon kanssa. Seinien napit saavat hetkeksi <b>kilven</b>.": "Every <b>40,000 points</b> you get a <b>roulette</b>. It picks a shake, a black hole, a magnet, nothing or, now and then, a <b>joker ball</b> that merges with any ball. The wall buttons get a <b>shield</b> for a moment.",
    "Ammu vaunun yläosassa lentäviä <b>tähtiä</b> ja <b>Nelli-sydämiä</b>, niin saat bonuspisteitä.": "Shoot the <b>stars</b> and <b>Nelli hearts</b> flying across the top of the wagon for bonus points.",
    "Saavutuksista saat <b>pokaaleja</b> vaunun pohjan hyllyille. Tartu pokaaliin sormella ja <b>heitä</b> sitä ympäri vaunua!": "Achievements give you <b>trophies</b> on the shelves at the bottom of the wagon. Grab a trophy with your finger and <b>throw</b> it around the wagon!",
