    "Pisteet ja ruletit säilyvät, kun siirryt seuraavalle tasolle.": "Your points and roulettes carry over to the next stage.",
    "Avautuu, kun läpäiset tason {0}.": "Opens when you beat stage {0}.",
    "Selvä!": "Got it!",
    "Kerää mahdollisimman paljon pisteitä ja läpäise tasot yhdistämällä kaksi suurinta palloa. Peli päättyy, jos pallot painavat molempia nappeja yhtä aikaa.": "Collect as many points as you can and beat the stages by merging the two biggest balls. The game ends if the balls press both buttons at once.",
    "Kerää kahdessa minuutissa niin paljon pisteitä kuin ehdit. Nappeihin ei voi hävitä.": "Collect as many points as you can in two minutes. You cannot lose to the buttons.",
    "Tavoite vaihtuu joka päivä klo 15. Kaikilla on sama pallojärjestys ja sama tavoite.": "The goal changes every day at 15:00 (Finnish time). Everyone gets the same ball order and the same goal.",
    "Ei mitään, vain rentoutumista. Pisteitä ei lasketa, eikä peliä voi hävitä.": "Nothing, just relax. No points are counted and you cannot lose.",
    "Kerää mahdollisimman paljon pisteitä, kun painovoiman suunta vaihtuu muutaman sekunnin välein. Peli päättyy, jos pallot painavat molempia nappeja.": "Collect as many points as you can while the direction of gravity changes every few seconds. The game ends if the balls press both buttons.",
    "Suorita {1} tehtävää järjestyksessä. Jokaisella tehtävällä on oma tavoitteensa, esimerkiksi tietty pallo rajatuilla laukauksilla tai pisteitä aikarajassa.": "Complete {1} missions in order. Every mission has its own goal, such as a certain ball within a limited number of shots or points within a time limit.",
