    "Kerää mahdollisimman paljon pisteitä ja läpäise tasot yhdistämällä kaksi suurinta palloa. Peli päättyy, jos pallot painavat molempia nappeja yhtä aikaa.": "Kogu võimalikult palju punkte ja läbi tasemed, ühendades kaks suurimat palli. Mäng lõpeb, kui pallid vajutavad mõlemat nuppu korraga.",
