    "Tavoite vaihtuu joka päivä klo 15. Kaikilla on sama pallojärjestys ja sama tavoite.": "Eesmärk vahetub iga päev kell 15 (Soome aja järgi). Kõigil on sama pallide järjekord ja sama eesmärk.",
