    "Ammu lippupalloja junavaunuun. Kaksi samaa maata yhdistyy isommaksi maaksi. Mikä mahtaa olla suurin?": "Lase lipupalle rongivagunisse. Kaks ühesugust maad ühinevad suuremaks maaks. Mis võiks olla suurim?",
