    "Mykistä äänet": "Couper le son",
    "Pelialue: vaunu täynnä lippupalloja": "Zone de jeu : un wagon plein de boules-drapeaux",
    "<b>Tähtää</b> hiirellä tai sormella. Mitä kauemmas osoitat, sitä kovempaa pallo lentää.": "<b>Vise</b> avec la souris ou le doigt. Plus tu pointes loin, plus la boule vole fort.",
    "<b>Ammu</b> klikkaamalla tai nostamalla sormen ruudulta.": "<b>Tire</b> en cliquant ou en levant le doigt de l'écran.",
    "Kevyt laukaus laskee pallon varovasti, kova laukaus <b>tönii ja litistää</b> muita.": "Un tir doux pose la boule délicatement, un tir fort <b>pousse et écrase</b> les autres.",
    "Vaunun seinissä on kaksi nappia. Jos pallot koskettavat <b>molempia nappeja</b> yhtä aikaa, peli päättyy.": "Il y a deux boutons sur les parois du wagon. Si des boules touchent <b>les deux boutons</b> en même temps, la partie est finie.",
    "Joka <b>40 000 pisteellä</b> saat <b>ruletin</b>. Se arpoo heilautuksen, mustan aukon, magneetin, ei mitään tai harvoin <b>jokeripallon</b>, joka yhdistyy minkä tahansa pallon kanssa. Seinien napit saavat hetkeksi <b>kilven</b>.": "Tous les <b>40 000 points</b>, tu gagnes une <b>roulette</b>. Elle tire une secousse, un trou noir, un aimant, rien ou parfois une <b>balle joker</b> qui fusionne avec n’importe quelle balle. Les boutons des parois reçoivent un <b>bouclier</b> un instant.",
    "Ammu vaunun yläosassa lentäviä <b>tähtiä</b> ja <b>Nelli-sydämiä</b>, niin saat bonuspisteitä.": "Touche les <b>étoiles</b> et les <b>cœurs de Nelli</b> qui volent en haut du wagon pour des points bonus.",
    "Saavutuksista saat <b>pokaaleja</b> vaunun pohjan hyllyille. Tartu pokaaliin sormella ja <b>heitä</b> sitä ympäri vaunua!": "Les succès te donnent des <b>trophées</b> sur les étagères au fond du wagon. Attrape un trophée avec le doigt et <b>lance-le</b> à travers le wagon !",
