    "Selvä!": "Compris !",
    "Kerää mahdollisimman paljon pisteitä ja läpäise tasot yhdistämällä kaksi suurinta palloa. Peli päättyy, jos pallot painavat molempia nappeja yhtä aikaa.": "Gagne le plus de points possible et termine les niveaux en fusionnant les deux plus grandes boules. La partie se termine si les boules appuient sur les deux boutons à la fois.",
    "Kerää kahdessa minuutissa niin paljon pisteitä kuin ehdit. Nappeihin ei voi hävitä.": "Gagne autant de points que possible en deux minutes. Les boutons ne peuvent pas te faire perdre.",
    "Tavoite vaihtuu joka päivä klo 15. Kaikilla on sama pallojärjestys ja sama tavoite.": "L’objectif change chaque jour à 15 h (heure finlandaise). Tout le monde a le même ordre de balles et le même objectif.",
    "Ei mitään, vain rentoutumista. Pisteitä ei lasketa, eikä peliä voi hävitä.": "Rien, juste se détendre. Aucun point n’est compté et tu ne peux pas perdre.",
    "Kerää mahdollisimman paljon pisteitä, kun painovoiman suunta vaihtuu muutaman sekunnin välein. Peli päättyy, jos pallot painavat molempia nappeja.": "Gagne le plus de points possible pendant que la gravité change de direction toutes les quelques secondes. La partie se termine si les boules appuient sur les deux boutons.",
    "Suorita {1} tehtävää järjestyksessä. Jokaisella tehtävällä on oma tavoitteensa, esimerkiksi tietty pallo rajatuilla laukauksilla tai pisteitä aikarajassa.": "Accomplis {1} missions dans l’ordre. Chaque mission a son propre objectif, par exemple une certaine boule en un nombre limité de tirs ou des points dans une limite de temps.",
