    "Ostettu: {0}! Se on nyt päälläsi.": "Acheté : {0} ! Tu le portes maintenant.",
    "Pelaamalla saat <b>kokemusta</b> ja <b>kolikoita</b>. Uusista pelaajatasoista saa palkintoja, ja kolikoilla voi ostaa <b>kaupasta</b> uusia tavaroita. Jokaisesta tasosta saa 1–3 <b>tähteä</b>.": "En jouant, tu gagnes de l’<b>expérience</b> et des <b>pièces</b>. Les nouveaux niveaux de joueur donnent des récompenses, et avec les pièces tu peux acheter de nouvelles choses à la <b>boutique</b>. Chaque niveau donne 1 à 3 <b>étoiles</b>.",
