    "Pallojärjestys ja tavoite pysyvät samoina, kunnes uusi haaste alkaa klo 15.": "Fanann ord na liathróidí agus an sprioc mar an gcéanna go dtí go dtosaíonn an chéad dúshlán eile ag 15:00.",
