    "Pelialue: vaunu täynnä lippupalloja": "Limistéar imeartha: vagán lán de liathróidí brataí",
    "<b>Tähtää</b> hiirellä tai sormella. Mitä kauemmas osoitat, sitä kovempaa pallo lentää.": "<b>Aimsigh</b> leis an luch nó le do mhéar. Dá fhaide a dhíríonn tú, is ea is láidre a eitlíonn an liathróid.",
    "<b>Ammu</b> klikkaamalla tai nostamalla sormen ruudulta.": "<b>Scaoil</b> trí chliceáil nó trí do mhéar a ardú den scáileán.",
    "Kevyt laukaus laskee pallon varovasti, kova laukaus <b>tönii ja litistää</b> muita.": "Leagann urchar bog an liathróid go cúramach, <b>brúnn agus brúitear</b> na cinn eile le hurchar láidir.",
    "Vaunun seinissä on kaksi nappia. Jos pallot koskettavat <b>molempia nappeja</b> yhtä aikaa, peli päättyy.": "Tá dhá chnaipe ar bhallaí an vagáin. Má bhaineann liathróidí leis an <b>dá chnaipe</b> ag an am céanna, tá an cluiche thart.",
    "Joka <b>40 000 pisteellä</b> saat <b>ruletin</b>. Se arpoo heilautuksen, mustan aukon, magneetin, ei mitään tai harvoin <b>jokeripallon</b>, joka yhdistyy minkä tahansa pallon kanssa. Seinien napit saavat hetkeksi <b>kilven</b>.": "Gach <b>40,000 pointe</b> faigheann tú <b>roulette</b>. Roghnaíonn sé croitheadh, poll dubh, maighnéad, faic nó, ó am go chéile, <b>liathróid joker</b> a chumascann le liathróid ar bith. Faigheann cnaipí an bhalla <b>sciath</b> ar feadh tamaillín.",
    "Ammu vaunun yläosassa lentäviä <b>tähtiä</b> ja <b>Nelli-sydämiä</b>, niin saat bonuspisteitä.": "Lámhaigh na <b>réaltaí</b> agus <b>croíthe Nelli</b> a eitlíonn thuas sa charráiste chun pointí bónais a fháil.",
    "Saavutuksista saat <b>pokaaleja</b> vaunun pohjan hyllyille. Tartu pokaaliin sormella ja <b>heitä</b> sitä ympäri vaunua!": "Faigheann tú <b>cornanna</b> ar na seilfeanna ag bun an vagáin as éachtaí. Beir ar chorn le do mhéar agus <b>caith</b> timpeall an vagáin é!",
