    "Yhdistä kaksi suurinta palloa ({0}), niin pääset seuraavalle tasolle.": "Cumaisc an dá liathróid is mó ({0}) chun dul ar aghaidh chuig an gcéad leibhéal eile.",
    "Kun yhdistät kaksi suurinta palloa, siirryt heti <b>uudelle tasolle</b> uusine palloineen. Ylemmillä tasoilla tietty pallo pitää saada <b>aikarajassa</b>.": "Nuair a chumascann tú an dá liathróid is mó, téann tú díreach chuig <b>leibhéal nua</b> le liathróidí nua. Ar na leibhéil is airde caithfidh tú liathróid áirithe a bhaint amach laistigh de <b>theorainn ama</b>.",
