    "Tavoite": "Sprioc",
    "Yhdistä kaksi suurinta palloa ({0}).": "Cumaisc an dá liathróid is mó ({0}).",
    "Silloin peli siirtyy heti tasolle {0}: {1}.": "Ansin téann an cluiche díreach ar aghaidh chuig leibhéal {0}: {1}.",
    "Tämä on teeman viimeinen taso.": "Seo an leibhéal deireanach den téama.",
    "Aikarajat": "Teorainneacha ama",
    "Jos aikaraja ylittyy, peli päättyy.": "Má ritheann teorainn ama amach, críochnaíonn an cluiche.",
    "Ei aikarajaa.": "Gan teorainn ama.",
    "Pisteet ja ruletit säilyvät, kun siirryt seuraavalle tasolle.": "Fanann na pointí agus na roulettes agat sa chéad leibhéal eile.",
    "Avautuu, kun läpäiset tason {0}.": "Osclaítear é nuair a chríochnaíonn tú leibhéal {0}.",
    "Selvä!": "Tuigim!",
    "Kerää mahdollisimman paljon pisteitä ja läpäise tasot yhdistämällä kaksi suurinta palloa. Peli päättyy, jos pallot painavat molempia nappeja yhtä aikaa.": "Bailigh an oiread pointí agus is féidir agus críochnaigh na leibhéil trí an dá liathróid is mó a chumasc. Críochnaíonn an cluiche má bhrúnn na liathróidí an dá chnaipe in éineacht.",
    "Kerää kahdessa minuutissa niin paljon pisteitä kuin ehdit. Nappeihin ei voi hävitä.": "Bailigh an oiread pointí agus is féidir leat i ndá nóiméad. Ní féidir leat cailleadh mar gheall ar na cnaipí.",
    "Tavoite vaihtuu joka päivä klo 15. Kaikilla on sama pallojärjestys ja sama tavoite.": "Athraíonn an sprioc gach lá ag 15:00 (am na Fionlainne). Faigheann gach duine an t-ord céanna liathróidí agus an sprioc chéanna.",
    "Ei mitään, vain rentoutumista. Pisteitä ei lasketa, eikä peliä voi hävitä.": "Faic, ach scíth a ligean. Ní chomhairtear pointí agus ní féidir leat cailleadh.",
    "Kerää mahdollisimman paljon pisteitä, kun painovoiman suunta vaihtuu muutaman sekunnin välein. Peli päättyy, jos pallot painavat molempia nappeja.": "Bailigh an oiread pointí agus is féidir agus treo an domhantarraingthe ag athrú gach cúpla soicind. Críochnaíonn an cluiche má bhrúnn na liathróidí an dá chnaipe.",
    "Suorita {1} tehtävää järjestyksessä. Jokaisella tehtävällä on oma tavoitteensa, esimerkiksi tietty pallo rajatuilla laukauksilla tai pisteitä aikarajassa.": "Críochnaigh {1} mhisean in ord. Tá a sprioc féin ag gach misean, mar shampla liathróid áirithe le líon teoranta urchar nó pointí laistigh de theorainn ama.",
