    "Erikoisasu pukee koko hahmon kerralla. Valitse Ei erikoisasua, niin omat valintasi palaavat.": "Gléasann culaith speisialta an carachtar ar fad in éineacht. Roghnaigh Gan chulaith chun do roghanna féin a fháil ar ais.",
    "{0}. pallo": "liathróid {0}",
    "Yhdistä kaksi suurinta palloa, niin pääset seuraavalle tasolle.": "Cumaisc an dá liathróid is mó chun dul ar aghaidh chuig an gcéad leibhéal eile.",
