    "Saa suurin pallo.": "Faigh an liathróid is mó.",
    "Saa {0}. pallo painovoimatilassa.": "Faigh liathróid {0} sa mhód domhantarraingthe.",
    "Ammu lippupalloja junavaunuun. Kaksi samaa maata yhdistyy isommaksi maaksi. Mikä mahtaa olla suurin?": "Caith liathróidí brataí isteach sa charráiste. Cumascann dhá thír chomhionanna i dtír níos mó. Cén ceann is mó, meas tú?",
    "Ammu jumalapalloja vaunuun. Kaksi samaa jumalaa yhdistyy mahtavammaksi. Kuka on mahtavin kaikista?": "Caith liathróidí déithe isteach sa charráiste. Cumascann dhá dhia chomhionanna i gceann níos cumhachtaí. Cé hé an duine is cumhachtaí?",
    "Ammu sydänpalloja vaunuun. Kaksi samaa sydäntä yhdistyy isommaksi. Millainen on suurin sydän?": "Caith liathróidí croí isteach sa charráiste. Cumascann dhá chroí chomhionanna i gceann níos mó. Cén chuma atá ar an gcroí is mó?",
    "Ammu laskupalloja vaunuun. Kaksi samaa laskua yhdistyy vaikeammaksi. Mikä on vaikein lasku?": "Caith liathróidí suime isteach sa charráiste. Cumascann dhá shuim chomhionanna i gceann níos deacra. Cén tsuim is deacra?",
