    "Mutkat": "Casaidh",
    "Välillä juna kaartaa: varoituksen jälkeen vaunu kallistuu ja pallot valuvat sivulle.": "Ó am go chéile tógann an traein casadh: tar éis rabhaidh claonann an carráiste agus sleamhnaíonn na liathróidí go dtí an taobh.",
