    "<b>Ammu</b> klikkaamalla tai nostamalla sormen ruudulta.": "<b>Lőj</b> kattintással vagy az ujjad felemelésével.",
    "Kevyt laukaus laskee pallon varovasti, kova laukaus <b>tönii ja litistää</b> muita.": "A lágy lövés óvatosan teszi le a golyót, az erős lövés <b>meglöki és összenyomja</b> a többit.",
    "Vaunun seinissä on kaksi nappia. Jos pallot koskettavat <b>molempia nappeja</b> yhtä aikaa, peli päättyy.": "A kocsi falain két gomb van. Ha a golyók egyszerre érintik <b>mindkét gombot</b>, vége a játéknak.",
    "Joka <b>40 000 pisteellä</b> saat <b>ruletin</b>. Se arpoo heilautuksen, mustan aukon, magneetin, ei mitään tai harvoin <b>jokeripallon</b>, joka yhdistyy minkä tahansa pallon kanssa. Seinien napit saavat hetkeksi <b>kilven</b>.": "Minden <b>40 000 pontért</b> kapsz egy <b>rulettet</b>. Kisorsol egy rázást, egy fekete lyukat, egy mágnest, semmit vagy ritkán egy <b>dzsókergolyót</b>, ami bármelyik golyóval összeolvad. A falgombok egy pillanatra <b>pajzsot</b> kapnak.",
    "Ammu vaunun yläosassa lentäviä <b>tähtiä</b> ja <b>Nelli-sydämiä</b>, niin saat bonuspisteitä.": "Lőj a vagon tetején repülő <b>csillagokra</b> és <b>Nelli-szívekre</b> bónuszpontokért.",
    "Saavutuksista saat <b>pokaaleja</b> vaunun pohjan hyllyille. Tartu pokaaliin sormella ja <b>heitä</b> sitä ympäri vaunua!": "A teljesítményekért <b>kupákat</b> kapsz a kocsi aljában lévő polcokra. Fogj meg egy kupát az ujjaddal, és <b>dobd</b> körbe a kocsiban!",
