    "Kerää mahdollisimman paljon pisteitä ja läpäise tasot yhdistämällä kaksi suurinta palloa. Peli päättyy, jos pallot painavat molempia nappeja yhtä aikaa.": "Gyűjts minél több pontot, és teljesítsd a pályákat a két legnagyobb golyó egyesítésével. A játék véget ér, ha a golyók egyszerre nyomják mindkét gombot.",
    "Kerää kahdessa minuutissa niin paljon pisteitä kuin ehdit. Nappeihin ei voi hävitä.": "Két perc alatt gyűjts annyi pontot, amennyit csak tudsz. A gombok miatt nem veszíthetsz.",
    "Tavoite vaihtuu joka päivä klo 15. Kaikilla on sama pallojärjestys ja sama tavoite.": "A cél minden nap 15 órakor (finn idő szerint) változik. Mindenki ugyanazt a golyósorrendet és célt kapja.",
    "Ei mitään, vain rentoutumista. Pisteitä ei lasketa, eikä peliä voi hävitä.": "Semmi, csak lazíts. Pontokat nem számolunk, és nem veszíthetsz.",
