    "Ammu lippupalloja junavaunuun. Kaksi samaa maata yhdistyy isommaksi maaksi. Mikä mahtaa olla suurin?": "Lőj zászlós golyókat a vagonba. Két egyforma ország egy nagyobbá olvad össze. Vajon melyik a legnagyobb?",
    "Ammu jumalapalloja vaunuun. Kaksi samaa jumalaa yhdistyy mahtavammaksi. Kuka on mahtavin kaikista?": "Lőj istengolyókat a vagonba. Két egyforma isten egy hatalmasabbá olvad össze. Ki a leghatalmasabb mind közül?",
    "Ammu sydänpalloja vaunuun. Kaksi samaa sydäntä yhdistyy isommaksi. Millainen on suurin sydän?": "Lőj szívgolyókat a vagonba. Két egyforma szív egy nagyobbá olvad össze. Milyen a legnagyobb szív?",
    "Ammu laskupalloja vaunuun. Kaksi samaa laskua yhdistyy vaikeammaksi. Mikä on vaikein lasku?": "Lőj feladatgolyókat a vagonba. Két egyforma feladat egy nehezebbé olvad össze. Melyik a legnehezebb feladat?",
