    "Ammu lippupalloja junavaunuun. Kaksi samaa maata yhdistyy isommaksi maaksi. Mikä mahtaa olla suurin?": "Lancia palle-bandiera nel vagone. Due paesi uguali si uniscono in uno più grande. Quale sarà il più grande?",
