    "<b>Tähtää</b> hiirellä tai sormella. Mitä kauemmas osoitat, sitä kovempaa pallo lentää.": "<b>Tēmē</b> ar peli vai pirkstu. Jo tālāk norādi, jo stiprāk bumba lido.",
