    "Pisteet ja ruletit säilyvät, kun siirryt seuraavalle tasolle.": "Punkti un ruletes saglabājas, pārejot uz nākamo līmeni.",
    "Avautuu, kun läpäiset tason {0}.": "Atveras, kad izej līmeni {0}.",
    "Selvä!": "Skaidrs!",
    "Kerää mahdollisimman paljon pisteitä ja läpäise tasot yhdistämällä kaksi suurinta palloa. Peli päättyy, jos pallot painavat molempia nappeja yhtä aikaa.": "Krāj pēc iespējas vairāk punktu un izej līmeņus, apvienojot divas lielākās bumbas. Spēle beidzas, ja bumbas vienlaikus spiež abas pogas.",
    "Kerää kahdessa minuutissa niin paljon pisteitä kuin ehdit. Nappeihin ei voi hävitä.": "Divās minūtēs savāc tik daudz punktu, cik paspēj. Pogu dēļ zaudēt nevar.",
    "Tavoite vaihtuu joka päivä klo 15. Kaikilla on sama pallojärjestys ja sama tavoite.": "Mērķis mainās katru dienu plkst. 15 (Somijas laiks). Visiem ir vienāda bumbu secība un vienāds mērķis.",
    "Ei mitään, vain rentoutumista. Pisteitä ei lasketa, eikä peliä voi hävitä.": "Neko, tikai atpūties. Punkti netiek skaitīti, un zaudēt nevar.",
    "Kerää mahdollisimman paljon pisteitä, kun painovoiman suunta vaihtuu muutaman sekunnin välein. Peli päättyy, jos pallot painavat molempia nappeja.": "Krāj pēc iespējas vairāk punktu, kamēr gravitācijas virziens mainās ik pēc dažām sekundēm. Spēle beidzas, ja bumbas spiež abas pogas.",
    "Suorita {1} tehtävää järjestyksessä. Jokaisella tehtävällä on oma tavoitteensa, esimerkiksi tietty pallo rajatuilla laukauksilla tai pisteitä aikarajassa.": "Izpildi {1} misijas pēc kārtas. Katrai misijai ir savs mērķis, piemēram, noteikta bumba ar ierobežotu šāvienu skaitu vai punkti laika limitā.",
