    "Selvä!": "Am înțeles!",
    "Kerää mahdollisimman paljon pisteitä ja läpäise tasot yhdistämällä kaksi suurinta palloa. Peli päättyy, jos pallot painavat molempia nappeja yhtä aikaa.": "Strânge cât mai multe puncte și termină nivelurile unind cele mai mari două bile. Jocul se termină dacă bilele apasă ambele butoane deodată.",
    "Kerää kahdessa minuutissa niin paljon pisteitä kuin ehdit. Nappeihin ei voi hävitä.": "Strânge cât mai multe puncte în două minute. Nu poți pierde din cauza butoanelor.",
    "Tavoite vaihtuu joka päivä klo 15. Kaikilla on sama pallojärjestys ja sama tavoite.": "Obiectivul se schimbă în fiecare zi la ora 15 (ora Finlandei). Toți au aceeași ordine a bilelor și același obiectiv.",
    "Ei mitään, vain rentoutumista. Pisteitä ei lasketa, eikä peliä voi hävitä.": "Nimic, doar relaxare. Nu se numără puncte și nu poți pierde.",
    "Kerää mahdollisimman paljon pisteitä, kun painovoiman suunta vaihtuu muutaman sekunnin välein. Peli päättyy, jos pallot painavat molempia nappeja.": "Strânge cât mai multe puncte în timp ce direcția gravitației se schimbă la câteva secunde. Jocul se termină dacă bilele apasă ambele butoane.",
    "Suorita {1} tehtävää järjestyksessä. Jokaisella tehtävällä on oma tavoitteensa, esimerkiksi tietty pallo rajatuilla laukauksilla tai pisteitä aikarajassa.": "Îndeplinește {1} misiuni în ordine. Fiecare misiune are obiectivul ei, de exemplu o anumită bilă din lovituri limitate sau puncte într-o limită de timp.",
