    "Ammu lippupalloja junavaunuun. Kaksi samaa maata yhdistyy isommaksi maaksi. Mikä mahtaa olla suurin?": "Стреляй шарами-флагами в вагон. Две одинаковые страны сливаются в большую. Какая же самая большая?",
