    "Ammu sydänpalloja vaunuun. Kaksi samaa sydäntä yhdistyy isommaksi. Millainen on suurin sydän?": "Стреляй шарами-сердцами в вагон. Два одинаковых сердца сливаются в большее. Какое самое большое сердце?",
