    "<b>Tähtää</b> hiirellä tai sormella. Mitä kauemmas osoitat, sitä kovempaa pallo lentää.": "<b>Sikta</b> med musen eller fingret. Ju längre bort du pekar, desto hårdare flyger bollen.",
    "<b>Ammu</b> klikkaamalla tai nostamalla sormen ruudulta.": "<b>Skjut</b> genom att klicka eller lyfta fingret från skärmen.",
    "Kevyt laukaus laskee pallon varovasti, kova laukaus <b>tönii ja litistää</b> muita.": "Ett mjukt skott lägger bollen försiktigt, ett hårt skott <b>knuffar och klämmer</b> de andra.",
    "Vaunun seinissä on kaksi nappia. Jos pallot koskettavat <b>molempia nappeja</b> yhtä aikaa, peli päättyy.": "Det finns två knappar i vagnens väggar. Om bollar rör <b>båda knapparna</b> samtidigt tar spelet slut.",
    "Joka <b>40 000 pisteellä</b> saat <b>ruletin</b>. Se arpoo heilautuksen, mustan aukon, magneetin, ei mitään tai harvoin <b>jokeripallon</b>, joka yhdistyy minkä tahansa pallon kanssa. Seinien napit saavat hetkeksi <b>kilven</b>.": "Var <b>40 000:e poäng</b> får du en <b>roulette</b>. Den lottar en skakning, ett svart hål, en magnet, ingenting eller ibland en <b>jokerboll</b> som slås ihop med vilken boll som helst. Väggknapparna får en <b>sköld</b> en stund.",
    "Ammu vaunun yläosassa lentäviä <b>tähtiä</b> ja <b>Nelli-sydämiä</b>, niin saat bonuspisteitä.": "Skjut på <b>stjärnorna</b> och <b>Nelli-hjärtana</b> som flyger högst upp i vagnen för bonuspoäng.",
    "Saavutuksista saat <b>pokaaleja</b> vaunun pohjan hyllyille. Tartu pokaaliin sormella ja <b>heitä</b> sitä ympäri vaunua!": "Prestationer ger dig <b>pokaler</b> på hyllorna längst ner i vagnen. Ta tag i en pokal med fingret och <b>kasta</b> den runt vagnen!",
