    "Pelialue: vaunu täynnä lippupalloja": "Oyun alanı: bayrak toplarıyla dolu bir vagon",
    "<b>Tähtää</b> hiirellä tai sormella. Mitä kauemmas osoitat, sitä kovempaa pallo lentää.": "Fareyle veya parmağınla <b>nişan al</b>. Ne kadar uzağı gösterirsen top o kadar güçlü uçar.",
    "<b>Ammu</b> klikkaamalla tai nostamalla sormen ruudulta.": "Tıklayarak veya parmağını ekrandan kaldırarak <b>at</b>.",
    "Kevyt laukaus laskee pallon varovasti, kova laukaus <b>tönii ja litistää</b> muita.": "Yumuşak atış topu nazikçe bırakır, sert atış diğerlerini <b>iter ve ezer</b>.",
    "Vaunun seinissä on kaksi nappia. Jos pallot koskettavat <b>molempia nappeja</b> yhtä aikaa, peli päättyy.": "Vagonun duvarlarında iki düğme var. Toplar aynı anda <b>iki düğmeye</b> de değerse oyun biter.",
    "Joka <b>40 000 pisteellä</b> saat <b>ruletin</b>. Se arpoo heilautuksen, mustan aukon, magneetin, ei mitään tai harvoin <b>jokeripallon</b>, joka yhdistyy minkä tahansa pallon kanssa. Seinien napit saavat hetkeksi <b>kilven</b>.": "Her <b>40.000 puanda</b> bir <b>rulet</b> kazanırsın. Sallama, kara delik, mıknatıs, hiçbir şey ya da arada bir her topla birleşen bir <b>joker top</b> çıkar. Duvar düğmeleri kısa bir süre <b>kalkan</b> alır.",
    "Ammu vaunun yläosassa lentäviä <b>tähtiä</b> ja <b>Nelli-sydämiä</b>, niin saat bonuspisteitä.": "Bonus puan için vagonun üstünde uçan <b>yıldızları</b> ve <b>Nelli kalplerini</b> vur.",
    "Saavutuksista saat <b>pokaaleja</b> vaunun pohjan hyllyille. Tartu pokaaliin sormella ja <b>heitä</b> sitä ympäri vaunua!": "Başarımlar sana vagonun dibindeki raflarda <b>kupalar</b> kazandırır. Bir kupayı parmağınla tut ve vagonun içinde <b>fırlat</b>!",
