    "Selvä!": "Anladım!",
    "Kerää mahdollisimman paljon pisteitä ja läpäise tasot yhdistämällä kaksi suurinta palloa. Peli päättyy, jos pallot painavat molempia nappeja yhtä aikaa.": "Olabildiğince çok puan topla ve en büyük iki topu birleştirerek seviyeleri geç. Toplar iki düğmeye aynı anda basarsa oyun biter.",
    "Kerää kahdessa minuutissa niin paljon pisteitä kuin ehdit. Nappeihin ei voi hävitä.": "İki dakikada yetişebildiğin kadar puan topla. Düğmeler yüzünden kaybedemezsin.",
    "Tavoite vaihtuu joka päivä klo 15. Kaikilla on sama pallojärjestys ja sama tavoite.": "Hedef her gün saat 15.00’te (Finlandiya saati) değişir. Herkes aynı top sırasını ve aynı hedefi alır.",
    "Ei mitään, vain rentoutumista. Pisteitä ei lasketa, eikä peliä voi hävitä.": "Hiçbir şey, sadece rahatla. Puan sayılmaz ve kaybedemezsin.",
    "Kerää mahdollisimman paljon pisteitä, kun painovoiman suunta vaihtuu muutaman sekunnin välein. Peli päättyy, jos pallot painavat molempia nappeja.": "Yerçekiminin yönü birkaç saniyede bir değişirken olabildiğince çok puan topla. Toplar iki düğmeye de basarsa oyun biter.",
    "Suorita {1} tehtävää järjestyksessä. Jokaisella tehtävällä on oma tavoitteensa, esimerkiksi tietty pallo rajatuilla laukauksilla tai pisteitä aikarajassa.": "{1} görevi sırayla tamamla. Her görevin kendi hedefi vardır; örneğin sınırlı atışla belirli bir top ya da süre sınırı içinde puan.",
