    "Ammu lippupalloja junavaunuun. Kaksi samaa maata yhdistyy isommaksi maaksi. Mikä mahtaa olla suurin?": "Bayrak toplarını tren vagonuna at. İki aynı ülke birleşip daha büyük bir ülke olur. En büyüğü ne olabilir?",
    "Ammu jumalapalloja vaunuun. Kaksi samaa jumalaa yhdistyy mahtavammaksi. Kuka on mahtavin kaikista?": "Tanrı toplarını vagona at. İki aynı tanrı birleşip daha güçlü olur. En güçlüsü kim?",
